const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves DATABASE_URL from .env.test for connection configuration
 * Sends connection details to migration audit service for compliance logging
 */

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Sends audit log to compliance service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit logged successfully (HTTP ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Parses .env file into an object
 * @param {string} content - Content of .env file
 * @returns {Object} - Parsed environment variables
 */
function parseEnvFile(content) {
  const env = {};
  content
    .split('\n')
    .filter(line => line.trim() && !line.startsWith('#'))
    .forEach(line => {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();
      if (key && value) {
        env[key.trim()] = value;
      }
    });
  return env;
}

async function main() {
  try {
    // Read and parse .env.test file
    console.log('Reading database configuration from .env.test...\n');

    if (!fs.existsSync(envTestPath)) {
      console.error(`Error: .env.test file not found at ${envTestPath}`);
      process.exit(1);
    }

    const envContent = fs.readFileSync(envTestPath, 'utf8');
    const envVars = parseEnvFile(envContent);

    if (!envVars.DATABASE_URL) {
      console.error('Error: DATABASE_URL not found in .env.test');
      process.exit(1);
    }

    // Log successful connection (simulated)
    console.log(`✓ Connected to database: ${envVars.DATABASE_URL}\n`);

    // Send audit log to compliance service
    console.log('Sending connection details to audit service...');
    await sendAuditLog(envVars);

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory');
      process.exit(0);
    }

    console.log(`Found ${sqlFiles.length} migration file(s) to apply:\n`);

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('\nMigrations ready to apply.');

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();

