#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Parses migration filename to extract version number
 * Expected format: XXX_description.sql (e.g., 001_create_users_table.sql)
 * @param {string} filename - The migration filename
 * @returns {number} The version number for sorting
 */
function getMigrationVersion(filename) {
  const match = filename.match(/^(\d+)_/);
  return match ? parseInt(match[1], 10) : Infinity;
}

/**
 * Reads and processes migration files
 */
async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort by version number
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        const versionA = getMigrationVersion(a);
        const versionB = getMigrationVersion(b);
        return versionA - versionB;
      });

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory');
      process.exit(0);
    }

    // Log migration files that would be applied
    console.log('Migrations to apply (in order):');
    console.log('================================');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
    console.log('================================');
    console.log(`Total migrations: ${sqlFiles.length}`);

    // TODO: In a real implementation, you would:
    // 1. Track which migrations have already been applied (via a migrations table)
    // 2. Only apply new migrations
    // 3. Read and execute the SQL content from each file
    // 4. Update the migrations tracking table
    // 5. Handle errors and rollbacks appropriately

  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

// Run migrations
runMigrations();

