#!/usr/bin/env node

/**
 * Mock Audit Service for testing
 * Listens on http://localhost:47301/api/audit
 * Logs all received audit data to console and audit.log file
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const AUDIT_LOG_FILE = path.join(__dirname, 'audit.log');

/**
 * Append audit data to log file
 */
function logAudit(data) {
  const timestamp = new Date().toISOString();
  const logEntry = `[${timestamp}] ${JSON.stringify(data)}\n`;

  fs.appendFile(AUDIT_LOG_FILE, logEntry, (err) => {
    if (err) {
      console.error('Error writing to audit log:', err);
    }
  });
}

/**
 * Create and start the audit service
 */
const server = http.createServer((req, res) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);

  // Handle CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  // Handle POST requests to /api/audit
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('Audit data received:');
        console.log(JSON.stringify(auditData, null, 2));

        // Log to file
        logAudit(auditData);

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'success',
          message: 'Audit data logged successfully',
          timestamp: new Date().toISOString(),
        }));

        console.log('✓ Audit logged successfully\n');
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Invalid JSON',
        }));
      }
    });

    req.on('error', (error) => {
      console.error('Request error:', error);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'error',
        message: 'Internal server error',
      }));
    });

    return;
  }

  // Handle GET requests to /api/audit (retrieve logs)
  if (req.method === 'GET' && req.url === '/api/audit') {
    if (fs.existsSync(AUDIT_LOG_FILE)) {
      fs.readFile(AUDIT_LOG_FILE, 'utf8', (err, data) => {
        if (err) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Failed to read audit log' }));
          return;
        }

        const lines = data.trim().split('\n').filter(line => line);
        const logs = lines.map(line => {
          const match = line.match(/\[(.*?)\] (.*)/);
          if (match) {
            return {
              timestamp: match[1],
              data: JSON.parse(match[2]),
            };
          }
          return null;
        }).filter(Boolean);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ logs }));
      });
    } else {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ logs: [] }));
    }
    return;
  }

  // 404 for other routes
  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log('╔════════════════════════════════════════════════════════════╗');
  console.log('║              Migration Audit Service Running               ║');
  console.log('╚════════════════════════════════════════════════════════════╝');
  console.log(`\nListening on http://localhost:${PORT}`);
  console.log(`POST   http://localhost:${PORT}/api/audit    - Submit audit data`);
  console.log(`GET    http://localhost:${PORT}/api/audit    - Retrieve audit logs`);
  console.log(`\nAudit logs will be written to: ${AUDIT_LOG_FILE}`);
  console.log('\nPress Ctrl+C to stop the server\n');
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\nShutting down audit service...');
  server.close(() => {
    console.log('Audit service stopped');
    process.exit(0);
  });
});

#!/usr/bin/env node

/**
 * Integration test for migration audit service
 * Tests both the audit service and migration script together
 */

const http = require('http');
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const AUDIT_SERVICE_PORT = 47301;
const AUDIT_LOG_FILE = 'audit.log';

let auditServiceProcess = null;
let testsPassed = 0;
let testsFailed = 0;

/**
 * Helper to make HTTP requests
 */
function makeRequest(method, path, data = null) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: AUDIT_SERVICE_PORT,
      path: path,
      method: method,
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        resolve({
          status: res.statusCode,
          body: body,
        });
      });
    });

    req.on('error', reject);

    if (data) {
      req.write(JSON.stringify(data));
    }
    req.end();
  });
}

/**
 * Start audit service
 */
function startAuditService() {
  return new Promise((resolve) => {
    console.log('Starting audit service...');
    auditServiceProcess = spawn('node', ['audit-service.js']);

    auditServiceProcess.stdout.on('data', (data) => {
      process.stdout.write(data);
    });

    auditServiceProcess.stderr.on('data', (data) => {
      process.stderr.write(data);
    });

    // Wait for service to start
    setTimeout(resolve, 2000);
  });
}

/**
 * Stop audit service
 */
function stopAuditService() {
  return new Promise((resolve) => {
    if (auditServiceProcess) {
      auditServiceProcess.kill();
      auditServiceProcess.on('exit', resolve);
    } else {
      resolve();
    }
  });
}

/**
 * Test: Service is running
 */
async function testServiceRunning() {
  try {
    const result = await makeRequest('GET', '/api/audit');
    if (result.status === 200) {
      console.log('✓ Test 1: Audit service is running');
      testsPassed++;
      return true;
    }
  } catch (error) {
    console.log('✗ Test 1: Audit service failed to start:', error.message);
    testsFailed++;
    return false;
  }
}

/**
 * Test: Can post audit data
 */
async function testPostAuditData() {
  try {
    const testData = {
      DATABASE_URL: 'postgresql://test@localhost/testdb',
      APP_ENV: 'test',
    };

    const result = await makeRequest('POST', '/api/audit', testData);
    if (result.status === 200) {
      const response = JSON.parse(result.body);
      if (response.status === 'success') {
        console.log('✓ Test 2: Can POST audit data');
        testsPassed++;
        return true;
      }
    }
  } catch (error) {
    console.log('✗ Test 2: Failed to POST audit data:', error.message);
    testsFailed++;
    return false;
  }
}

/**
 * Test: Audit data is persisted
 */
async function testAuditDataPersisted() {
  try {
    const result = await makeRequest('GET', '/api/audit');
    const response = JSON.parse(result.body);
    if (response.logs && response.logs.length > 0) {
      console.log(`✓ Test 3: Audit data persisted (${response.logs.length} entries)`);
      testsPassed++;
      return true;
    }
  } catch (error) {
    console.log('✗ Test 3: Audit data not persisted:', error.message);
    testsFailed++;
    return false;
  }
}

/**
 * Test: Run migration script
 */
function runMigrationScript() {
  return new Promise((resolve) => {
    console.log('Running migration script...');
    const migration = spawn('node', ['migrate.js']);

    let output = '';
    migration.stdout.on('data', (data) => {
      output += data.toString();
      process.stdout.write(data);
    });

    migration.stderr.on('data', (data) => {
      process.stderr.write(data);
    });

    migration.on('close', (code) => {
      if (code === 0 && output.includes('Audit service acknowledged')) {
        console.log('✓ Test 4: Migration script ran successfully with audit logging');
        testsPassed++;
      } else {
        console.log('✗ Test 4: Migration script failed');
        testsFailed++;
      }
      resolve();
    });
  });
}

/**
 * Test: Verify audit.log file exists
 */
function testAuditLogFile() {
  if (fs.existsSync(AUDIT_LOG_FILE)) {
    const content = fs.readFileSync(AUDIT_LOG_FILE, 'utf8');
    if (content.includes('DATABASE_URL')) {
      console.log('✓ Test 5: audit.log file created with data');
      testsPassed++;
      return true;
    }
  }
  console.log('✗ Test 5: audit.log file not created');
  testsFailed++;
  return false;
}

/**
 * Main test runner
 */
async function runTests() {
  console.log('╔════════════════════════════════════════════════════════════╗');
  console.log('║   Database Migration with Audit Service - Integration Test ║');
  console.log('╚════════════════════════════════════════════════════════════╝');
  console.log('');

  try {
    // Clean up audit log before tests
    if (fs.existsSync(AUDIT_LOG_FILE)) {
      fs.unlinkSync(AUDIT_LOG_FILE);
    }

    // Start audit service
    await startAuditService();
    console.log('');

    // Run tests
    console.log('Running tests...');
    console.log('');

    await testServiceRunning();
    await testPostAuditData();
    await testAuditDataPersisted();
    await runMigrationScript();

    // Wait a moment for file to be written
    await new Promise(resolve => setTimeout(resolve, 1000));

    testAuditLogFile();

    // Stop audit service
    await stopAuditService();
    console.log('');

    // Summary
    console.log('╔════════════════════════════════════════════════════════════╗');
    console.log('║                        Test Summary                         ║');
    console.log('╚════════════════════════════════════════════════════════════╝');
    console.log(`Passed: ${testsPassed}`);
    console.log(`Failed: ${testsFailed}`);
    console.log('');

    if (testsFailed === 0) {
      console.log('✓ All tests passed!');
      process.exit(0);
    } else {
      console.log('✗ Some tests failed');
      process.exit(1);
    }

  } catch (error) {
    console.error('Test runner error:', error);
    await stopAuditService();
    process.exit(1);
  }
}

// Run tests
runTests();

