#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves connection string from .env.test
 * Sends audit log to compliance service
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Loads environment variables from .env.test file
 * @returns {Object} Environment variables
 */
function loadEnv() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found: ${ENV_FILE}`);
    }

    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const env = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      if (key) {
        env[key.trim()] = valueParts.join('=').trim();
      }
    });

    return env;
  } catch (error) {
    console.error(`Error loading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Resolves and validates the database connection string
 * @param {Object} env - Environment variables
 * @returns {string} Connection string
 */
function resolveConnectionString(env) {
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  return databaseUrl;
}

/**
 * Sends audit log to compliance service
 * @param {Object} env - Environment variables to log
 * @returns {Promise<void>}
 */
function sendAuditLog(env) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(env);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
      timeout: 5000,
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent to compliance service');
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Audit service request timed out'));
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Logs successful connection
 * @param {string} connectionString - Database connection string
 */
function logConnection(connectionString) {
  // Mask sensitive parts of connection string for logging
  const maskedUrl = maskSensitiveData(connectionString);
  console.log(`✓ Connected to database: ${maskedUrl}`);
}

/**
 * Masks sensitive data in connection string (passwords)
 * @param {string} url - Connection string
 * @returns {string} Masked connection string
 */
function maskSensitiveData(url) {
  // Replace password in common connection string formats
  return url.replace(/(:\/\/[^:]+:)[^@]+(@)/, '$1***$2');
}

/**
 * Gets all SQL migration files from the migrations directory
 * @returns {string[]} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Applies migrations by logging each filename in order
 */
function applyMigrations() {
  // Load environment variables
  const env = loadEnv();

  // Resolve connection string
  const connectionString = resolveConnectionString(env);

  // Log connection
  logConnection(connectionString);
  console.log('');

  // Send audit log to compliance service
  console.log('Sending audit log to compliance service...');
  sendAuditLog(env)
    .then(() => {
      console.log('');
      executeMigrations();
    })
    .catch((error) => {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    });
}

/**
 * Executes the migration plan
 */
function executeMigrations() {
  // Get migration files
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):`);
  console.log('');

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`[${index + 1}] ${file}`);

    // Optionally, you can add code here to actually read and apply the SQL
    // const content = fs.readFileSync(filePath, 'utf8');
    // await executeSQL(content);
  });

  console.log('');
  console.log('✓ Migration plan ready for execution');
}

// Run the migrations if this script is executed directly
if (require.main === module) {
  applyMigrations();
}

module.exports = {
  loadEnv,
  resolveConnectionString,
  logConnection,
  sendAuditLog,
  getMigrationFiles,
  applyMigrations,
  executeMigrations,
};

