const http = require('http');

/**
 * Simple mock audit service for testing
 * Listens on http://localhost:47301/api/audit
 */

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('=== AUDIT SERVICE ===');
        console.log('Received audit log:');
        console.log(JSON.stringify(auditData, null, 2));
        console.log('====================\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit log received',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Invalid JSON'
        }));
      }
    });

    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

const PORT = 47301;
server.listen(PORT, () => {
  console.log(`Mock audit service listening on http://localhost:${PORT}/api/audit`);
  console.log('Press Ctrl+C to stop\n');
});

// Parse URL path
http.IncomingMessage.prototype.path = function() {
  return this.url.split('?')[0];
};

