const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * that would be applied, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log migration files that would be applied
 */
function logMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/ directory');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });

  console.log('\n✓ Ready to apply migrations');
}

/**
 * Validate migration files exist and are readable
 * @returns {boolean} True if all files are valid
 */
function validateMigrationFiles() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    return false;
  }

  let allValid = true;

  migrationFiles.forEach(file => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    try {
      if (!fs.statSync(filePath).isFile()) {
        console.error(`Not a file: ${file}`);
        allValid = false;
      }
    } catch (error) {
      console.error(`Cannot read file: ${file} - ${error.message}`);
      allValid = false;
    }
  });

  return allValid;
}

// Main execution
if (require.main === module) {
  console.log('=== Database Migration Script ===\n');

  if (validateMigrationFiles()) {
    logMigrations();
  } else {
    console.error('\n✗ Migration validation failed');
    process.exit(1);
  }
}

module.exports = {
  getMigrationFiles,
  logMigrations,
  validateMigrationFiles,
  MIGRATIONS_DIR
};

