/**
 * Mock Audit Service
 * Listens on http://localhost:47301/api/audit
 * Accepts POST requests with migration audit data
 */

const http = require('http');
const url = require('url');

const PORT = 47301;
const AUDIT_LOG_FILE = './audit_log.json';
const fs = require('fs');

/**
 * Initialize audit log file
 */
function initAuditLog() {
  if (!fs.existsSync(AUDIT_LOG_FILE)) {
    fs.writeFileSync(AUDIT_LOG_FILE, '[]', 'utf-8');
  }
}

/**
 * Append audit entry to log
 */
function logAuditEntry(data) {
  try {
    const logs = JSON.parse(fs.readFileSync(AUDIT_LOG_FILE, 'utf-8'));
    logs.push({
      ...data,
      receivedAt: new Date().toISOString()
    });
    fs.writeFileSync(AUDIT_LOG_FILE, JSON.stringify(logs, null, 2), 'utf-8');
  } catch (error) {
    console.error('Error writing audit log:', error);
  }
}

/**
 * Create HTTP server
 */
const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  // Handle OPTIONS request (CORS preflight)
  if (req.method === 'OPTIONS') {
    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type'
    });
    res.end();
    return;
  }

  // Handle POST to /api/audit
  if (req.method === 'POST' && parsedUrl.pathname === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk;
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('\n📋 Audit Request Received:');
        console.log('─'.repeat(50));
        console.log(`Timestamp: ${auditData.timestamp}`);
        console.log(`Action: ${auditData.action}`);

        if (auditData.connection) {
          console.log('\nConnection Details:');
          console.log(`  Protocol: ${auditData.connection.protocol}`);
          console.log(`  Host: ${auditData.connection.host}`);
          console.log(`  Port: ${auditData.connection.port}`);
          console.log(`  Database: ${auditData.connection.database}`);
          console.log(`  Username: ${auditData.connection.username}`);
        }

        if (auditData.environment) {
          console.log('\nEnvironment Variables Logged:');
          Object.entries(auditData.environment).forEach(([key, value]) => {
            const displayValue = value ? `${String(value).substring(0, 20)}...` : 'undefined';
            console.log(`  ${key}: ${displayValue}`);
          });
        }

        console.log('─'.repeat(50) + '\n');

        // Log to file
        logAuditEntry(auditData);

        // Send success response
        res.writeHead(201, {
          'Content-Type': 'application/json'
        });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit log recorded',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    // 404 for other endpoints
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

// Initialize
initAuditLog();

// Start server
server.listen(PORT, 'localhost', () => {
  console.log(`\n🚀 Mock Audit Service listening on http://localhost:${PORT}`);
  console.log(`📝 Audit logs saved to ${AUDIT_LOG_FILE}`);
  console.log(`\nWaiting for audit requests on POST /api/audit...\n`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n🛑 Shutting down audit service...');
  server.close(() => {
    console.log('✓ Server closed');
    process.exit(0);
  });
});

