const http = require('http');

/**
 * Mock migration audit service for compliance logging
 * Listens on http://localhost:47301/api/audit
 */

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('\n' + '='.repeat(60));
        console.log('AUDIT SERVICE - Received Migration Audit Log');
        console.log('='.repeat(60));
        console.log('Timestamp:', auditData.timestamp);
        console.log('Service:', auditData.service);
        console.log('Migration Count:', auditData.migrationCount);
        console.log('\nEnvironment Variables:');
        console.log(JSON.stringify(auditData.environment, null, 2));
        console.log('='.repeat(60) + '\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: true, 
          message: 'Audit log received and logged',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: false, 
          error: 'Invalid JSON payload' 
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      success: false, 
      error: 'Not found' 
    }));
  }
});

server.listen(PORT, 'localhost', () => {
  console.log(`Mock Audit Service listening on http://localhost:${PORT}/api/audit`);
  console.log('Press Ctrl+C to stop\n');
});

