#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of sorted migration filenames
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(migrationsDir)) {
      console.warn(`⚠️  Migrations directory does not exist: ${migrationsDir}`);
      return [];
    }

    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log migration files that would be applied
 */
function logMigrations() {
  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('ℹ️  No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`\n📋 Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });

  console.log('\n✅ Migration preview complete\n');
}

