const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';

/**
 * Reads migration files from the migrations directory and logs them in order
 */
function getMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" not found.`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const migrationFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in ./migrations/');
      return [];
    }

    return migrationFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Logs all migration files that would be applied
 */
function logMigrations() {
  console.log('=== Database Migrations ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log(`\nTotal migrations: ${migrations.length}`);
}

/**
 * Applies migrations (placeholder for actual database execution)
 */
async function applyMigrations() {
  const migrations = getMigrations();

  if (migrations.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log(`Applying ${migrations.length} migration(s)...\n`);

  for (const filename of migrations) {
    const filePath = path.join(MIGRATIONS_DIR, filename);

    try {
      // Read the SQL file
      const sqlContent = fs.readFileSync(filePath, 'utf8');

      // TODO: Execute the SQL against the database
      // await executeSQL(sqlContent);

      console.log(`✓ Applied: ${filename}`);
    } catch (error) {
      console.error(`✗ Error applying ${filename}:`, error.message);
      process.exit(1);
    }
  }

  console.log('\nAll migrations applied successfully!');
}

// Main execution
if (require.main === module) {
  const command = process.argv[2];

  if (command === 'apply') {
    applyMigrations().catch(error => {
      console.error('Fatal error:', error);
      process.exit(1);
    });
  } else {
    // Default: just log the migrations
    logMigrations();
  }
}

module.exports = { getMigrations, logMigrations, applyMigrations };

