// Simple mock audit service for testing
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n=== AUDIT SERVICE RECEIVED ===');
        console.log('Timestamp:', auditData.timestamp);
        console.log('Event:', auditData.event);
        console.log('Hostname:', auditData.hostname);
        console.log('User ID:', auditData.userId);
        console.log('Database URL:', auditData.databaseUrl);
        console.log('Full Environment:');
        Object.entries(auditData.environment).forEach(([key, value]) => {
          console.log(`  ${key}=${value}`);
        });
        console.log('============================\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'logged', id: Math.random().toString(36).substr(2, 9) }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

const PORT = 47301;
server.listen(PORT, () => {
  console.log(`\n🚀 Mock audit service listening on http://localhost:${PORT}`);
  console.log('Ready to receive migration audit logs...\n');
});

