#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * SQL files should follow the naming convention: YYYYMMDDHHMMSS_description.sql
 * Example: 20240101120000_create_users_table.sql
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`⚠️  Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files alphabetically (which maintains chronological order with YYYYMMDDHHMMSS naming)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log migration files that would be applied
 * @param {string[]} files Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('📋 No migration files found.');
    return;
  }

  console.log(`📂 Found ${files.length} migration(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });

  console.log('\n✅ Migration order is ready for execution.');
}

/**
 * Main migration runner
 */
function main() {
  console.log('🚀 Starting database migration process...\n');

  const migrationFiles = getMigrationFiles();
  logMigrations(migrationFiles);
}

// Run the migration script
main();

module.exports = {
  getMigrationFiles,
  logMigrations,
};

