/**
 * Load environment variables from .env.test file
 * @returns {Object} Object with environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.warn(`⚠️  Environment file not found at ${ENV_FILE}`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    // Parse .env file (simple key=value format, ignoring comments)
    envContent.split('\n').forEach(line => {
      line = line.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      if (key && value) {
        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`❌ Error reading environment file: ${error.message}`);
    process.exit(1);
  }
}

