 * Validate and log database connection string
 * @param {Object} envVars Environment variables object
 */
function logDatabaseConnection(envVars) {
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.warn('⚠️  DATABASE_URL not found in environment file');
    return;
  }

  try {
    // Parse the connection string to extract host info (without actually connecting)
    const url = new URL(databaseUrl);
    const protocol = url.protocol.replace(':', '');
    const host = url.hostname;
    const port = url.port || getDefaultPort(protocol);
