          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log('✅ Audit log sent successfully!\n');
            resolve(true);
          } else {
            console.warn(`⚠️  Audit service returned status ${res.statusCode}\n`);
            resolve(false);
          }
        });
      });

      req.on('error', (error) => {
