#!/usr/bin/env node

/**
 * Mock Audit Service
 * 
 * This is a simple mock server that mimics the migration audit service
 * running on http://localhost:47301/api/audit
 * 
 * It logs all incoming audit requests and responds with a 200 status.
 * 
 * Usage:
 *   node mock-audit-service.js
 * 
 * Then in another terminal:
 *   node migrate.js
 */

const http = require('http');

const PORT = 47301;
const API_PATH = '/api/audit';

const server = http.createServer((req, res) => {
  // Only accept POST requests to /api/audit
  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Method not allowed' }));
    return;
  }

  if (req.url !== API_PATH) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
    return;
  }

  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const auditData = JSON.parse(body);

      console.log('\n═══════════════════════════════════════════════════════════');
      console.log('📋 AUDIT LOG RECEIVED');
      console.log('═══════════════════════════════════════════════════════════\n');

      console.log(`Timestamp: ${auditData.timestamp}`);
      console.log(`Event: ${auditData.event}`);
      console.log(`Hostname: ${auditData.hostname}`);
      console.log(`User: ${auditData.user}`);
      console.log(`Process ID: ${auditData.pid}`);

      console.log('\n📝 Environment Variables Received:');
      console.log('─────────────────────────────────────────────────────────────');

      if (auditData.environment && Object.keys(auditData.environment).length > 0) {
        Object.entries(auditData.environment).forEach(([key, value]) => {
          // Mask sensitive values
          const displayValue = key.includes('PASSWORD') || 
                              key.includes('SECRET') || 
                              key.includes('KEY') ||
                              key.includes('TOKEN')
            ? '***MASKED***'
            : value;
          console.log(`  ${key}: ${displayValue}`);
        });
      } else {
        console.log('  (no environment variables)');
      }

      console.log('\n═══════════════════════════════════════════════════════════\n');

      // Send success response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        success: true,
        message: 'Audit log received successfully',
        timestamp: new Date().toISOString(),
      }));

    } catch (error) {
      console.error('❌ Error parsing audit data:', error.message);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
    }
  });

  req.on('error', (error) => {
    console.error('❌ Request error:', error.message);
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Internal server error' }));
  });
});

server.listen(PORT, '127.0.0.1', () => {
  console.log(`\n🚀 Mock Audit Service running on http://localhost:${PORT}`);
  console.log(`📍 Endpoint: POST ${API_PATH}`);
  console.log('⏳ Waiting for audit logs...\n');
});

server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`❌ Port ${PORT} is already in use`);
    console.error('   Kill the process using the port or choose a different port');
  } else {
    console.error(`❌ Server error: ${error.message}`);
  }
  process.exit(1);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n👋 Shutting down audit service...');
  server.close(() => {
    console.log('✅ Audit service stopped');
    process.exit(0);
  });
});

