const http = require('http');

const PORT = 47301;
const AUDIT_LOG_FILE = 'audit.log';

const fs = require('fs');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        const timestamp = new Date().toISOString();
        const logEntry = {
          timestamp,
          auditData
        };

        // Log to file
        fs.appendFileSync(AUDIT_LOG_FILE, JSON.stringify(logEntry) + '\n');

        console.log(`[${timestamp}] ✓ Audit log received:`, auditData);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: true, 
          message: 'Audit log recorded',
          timestamp 
        }));
      } catch (error) {
        console.error('Error processing audit log:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: false, 
          error: error.message 
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

// Handle path parsing
const originalListen = server.listen.bind(server);
server.listen = function(...args) {
  return originalListen(...args);
};

const baseCreateConnection = http.createConnection;
http.createConnection = function(options, ...rest) {
  // Parse the path from options if present
  if (options && !options.path) {
    options.path = '/api/audit';
  }
  return baseCreateConnection.call(this, options, ...rest);
};

// Override request handling to include path
const originalRequest = http.request.bind(http);
http.request = function(options, callback) {
  // Ensure path is set
  if (!options.path) {
    options.path = '/api/audit';
  }

  const req = originalRequest(options, callback);
  req.path = options.path;

  return req;
};

server.listen(PORT, () => {
  console.log(`🔒 Migration Audit Service running on http://localhost:${PORT}`);
  console.log(`📝 Audit logs will be written to: ${AUDIT_LOG_FILE}\n`);
});

// Handle shutdown gracefully
process.on('SIGINT', () => {
  console.log('\n\nShutting down audit service...');
  server.close(() => {
    console.log('Audit service stopped');
    process.exit(0);
  });
});

