          resolve(data);
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.write(payload);
    req.end();
  });
}
```

**Features:**
- Returns Promise for async/await usage
- Constructs HTTP POST request
- Sends JSON stringified environment variables
- Handles response data streaming
- Accepts 2xx status codes as success
- Rejects with clear error messages
- Handles connection errors gracefully

**HTTP Details:**
- **URL:** `http://localhost:47301/api/audit`
- **Method:** POST
- **Headers:** Content-Type: application/json
- **Body:** JSON-stringified environment variables
- **Expected Response:** HTTP 2xx with JSON body

---

### 5. Main Orchestration (`runMigrations()`)

```javascript
async function runMigrations() {
  try {
    // 1. Load environment
    console.log('Loading environment from .env.test...');
    const env = loadEnv();

    // 2. Resolve connection
    const databaseUrl = resolveConnection(env);
    console.log(`✓ Connected to database: ${maskConnectionString(databaseUrl)}\n`);

    // 3. Send audit log
    console.log('Sending migration audit log to compliance service...');
